const NEXUS_URL = "https://TU-DOMINIO.com"; // sin barra final
const state = $getWorkflowStaticData("global");
// Primera vez: solo se avisa de lo que pase DESDE ahora (no se inunda con el historial).
if (!state.since && !state.after) state.since = new Date().toISOString();
const params = { limit: 100 };
if (state.after) params.after = state.after;
else params.since = state.since;
return [{ json: { url: NEXUS_URL + "/api/v1/events", params } }];

const state = $getWorkflowStaticData("global");
const body = $input.first().json;
const events = (body && body.data && body.data.events) || [];
if (!events.length) return [];
// El cursor avanza al último evento recibido: si n8n estuvo apagado, la próxima consulta trae todo lo pendiente.
state.after = body.data.next;
delete state.since;
const money = (v) => "$" + Number(v).toLocaleString("es-CO");
const lines = events.filter((e) => e.type === "sale.completed").map((e) => {
  const d = e.data || {};
  return "💰 Venta " + (d.receipt || "") + ": " + money(d.amount) + " (" + (d.method || "") + ")";
});
if (!lines.length) return [];
return [{ json: { text: lines.join("\n") } }];
